  "",
  "    /* —— لیست آیتم‌های «هدرهای حکم» داخل کرکره (پیش‌فرض بسته) —— */",
  "    function collapseDecreeHeadersList() {",
  "      try {",
  "        // اگر کرکره هست و هنوز لیست را داخل خود دارد، کاری نکن",
  "        var existing = document.getElementById('pspDecreeHeadersAcc');",
  "        if (existing) {",
  "          var stillHas = existing.querySelectorAll('input[type=\"checkbox\"], [role=\"checkbox\"]').length;",
  "          if (stillHas >= 2) return;",
  "          // لیست از بین رفته — کرکرهٔ خالی را بردار و دوباره بساز",
  "          try { if (existing.parentNode) existing.parentNode.removeChild(existing); } catch (eRm) {}",
  "        }",
  "",
  "        // استراتژی: پیدا کردن همهٔ گره‌هایی که متن «مشمول حکم» دارند",
  "        var hits = [];",
  "        var walkerNodes = document.querySelectorAll('label, span, div, li, td, p, small');",
  "        for (var wi = 0; wi < walkerNodes.length; wi++) {",
  "          var wn = walkerNodes[wi];",
  "          if (wn.closest && (wn.closest('#pspDecreeHeadersAcc') || wn.closest('#panel-portalatt') || wn.closest('#pspPortalPanel'))) continue;",
  "          var wt = norm(wn.textContent);",
  "          // فقط گره‌های برگ‌مانند با متن کوتاه",
  "          if (wt === 'مشمول حکم' || wt === 'مشمول عیدی/سنوات' || wt === 'مشمول عیدی / سنوات') {",
  "            hits.push(wn);",
  "          }",
  "        }",
  "        if (hits.length < 2) {",
  "          // fallback: چک‌باکس‌ها",
  "          var cbsAll = document.querySelectorAll('input[type=\"checkbox\"]');",
  "          for (var ci = 0; ci < cbsAll.length; ci++) {",
  "            var cb = cbsAll[ci];",
  "            if (cb.closest && (cb.closest('#pspDecreeHeadersAcc') || cb.closest('#panel-portalatt'))) continue;",
  "            var lab = '';",
  "            try {",
  "              if (cb.id) { var ll = document.querySelector('label[for=\"'+cb.id+'\"]'); if (ll) lab = norm(ll.textContent); }",
  "              if (!lab && cb.parentElement) lab = norm(cb.parentElement.textContent).slice(0, 40);",
  "            } catch (eL) {}",
  "            if (/مشمول\\s*حکم|مشمول\\s*عیدی/.test(lab)) hits.push(cb);",
  "          }",
  "        }",
  "        if (hits.length < 2) return;",
  "",
  "        // جد مشترک حداقلی که همهٔ hits را دارد",
  "        function commonAncestor(nodes) {",
  "          if (!nodes.length) return null;",
  "          var a = nodes[0];",
  "          while (a) {",
  "            var ok = true;",
  "            for (var i = 1; i < nodes.length; i++) {",
  "              if (!a.contains(nodes[i])) { ok = false; break; }",
  "            }",
  "            if (ok) return a;",
  "            a = a.parentElement;",
  "          }",
  "          return null;",
  "        }",
  "        var listBox = commonAncestor(hits);",
  "        if (!listBox) return;",
  "        // اگر جد خیلی بزرگ است (کل صفحه)، یک سطح پایین‌تر با بیشترین hit را بگیر",
  "        if (listBox === document.body || listBox === document.documentElement || (listBox.querySelectorAll && listBox.querySelectorAll('button.tab-btn, .tab-btn').length > 3)) {",
  "          var best = null, bestN = 0;",
  "          var cands = listBox.querySelectorAll('div, section, ul, ol');",
  "          for (var xi = 0; xi < cands.length; xi++) {",
  "            var c = cands[xi];",
  "            if (c.closest && c.closest('#panel-portalatt')) continue;",
  "            var n = 0;",
  "            for (var hi = 0; hi < hits.length; hi++) { if (c.contains(hits[hi])) n++; }",
  "            if (n >= 2 && n >= bestN && c !== listBox) {",
  "              // ترجیح ظرف کوچک‌تر با همان پوشش",
  "              if (n > bestN || !best || c.querySelectorAll('*').length < best.querySelectorAll('*').length) {",
  "                best = c; bestN = n;",
  "              }",
  "            }",
  "          }",
  "          if (best) listBox = best;",
