  "    /* —— آیتم‌های اصلی حکم (حقوق پایه، پایه سنوات، …) داخل کرکره —— */",
  "    function collapseDecreeMainItems() {",
  "      try {",
  "        if (document.getElementById('pspDecreeMainAcc')) return;",
  "        var tabTxt = activeTabText();",
  "        if (!/حکم/.test(tabTxt)) return;",
