  "        btn.type = 'button';",
  "        btn.style.cssText = 'width:100%;text-align:right;padding:10px 14px;background:#ecfdf5;border:0;cursor:pointer;font-family:inherit;font-weight:700;color:#0f766e;font-size:0.88rem;display:flex;align-items:center;gap:8px;';",
  "        var open = false;",
  "        function renderBtn() {",
  "          btn.innerHTML = '<span style=\"display:inline-block;width:1.2em;text-align:center;font-size:1.1rem;\">' + (open ? '−' : '+') + '</span> آیتم‌های اصلی حکم <span style=\"font-weight:500;color:#64748b;font-size:0.78rem;\">(' + found.length + ' مورد — کلیک برای ' + (open ? 'جمع کردن' : 'باز کردن') + ')</span>';",
  "        }",
  "        renderBtn();",
  "        var body = document.createElement('div');",
  "        body.style.cssText = 'padding:8px 10px;display:none;';",
  "        var first = found[0];",
  "        parent.insertBefore(host, first);",
  "        found.forEach(function(g) { body.appendChild(g); });",
  "        host.appendChild(btn);",
  "        host.appendChild(body);",
