  "  function pspHideEmpTableColumns() {",
  "    var table = document.getElementById('empTable');",
  "    if (!table) return;",
  "    var hideNames = ['حق اولاد', 'حقوق پایه', 'بانک', 'معافیت', 'وام'];",
  "    function shouldHide(text) {",
  "      var t = String(text || '').replace(/\\u200c/g, '').replace(/\\s+/g, ' ').trim();",
  "      for (var i = 0; i < hideNames.length; i++) {",
  "        if (t.indexOf(hideNames[i]) >= 0) return true;",
  "      }",
  "      return false;",
  "    }",
  "    var headRows = table.querySelectorAll('thead tr');",
  "    if (!headRows.length) return;",
  "    // پیدا کردن ایندکس ستون‌ها از اولین ردیف هدر",
  "    var hideIdx = {};",
  "    var cells0 = headRows[0].querySelectorAll('th,td');",
  "    for (var i = 0; i < cells0.length; i++) {",
  "      if (shouldHide(cells0[i].textContent)) {",
  "        hideIdx[i] = true;",
  "        cells0[i].classList.add('psp-col-hide');",
  "        cells0[i].style.display = 'none';",
  "      }",
  "    }",
  "    // ردیف فیلترها",
  "    for (var r = 1; r < headRows.length; r++) {",
  "      var cells = headRows[r].querySelectorAll('th,td');",
  "      Object.keys(hideIdx).forEach(function(ix) {",
  "        var i2 = Number(ix);",
  "        if (cells[i2]) { cells[i2].classList.add('psp-col-hide'); cells[i2].style.display = 'none'; }",
  "      });",
  "    }",
  "    table.querySelectorAll('tbody tr').forEach(function(tr) {",
  "      var tds = tr.children;",
  "      Object.keys(hideIdx).forEach(function(ix) {",
  "        var i2 = Number(ix);",
  "        if (tds[i2]) { tds[i2].classList.add('psp-col-hide'); tds[i2].style.display = 'none'; }",
  "      });",
  "    });",
  "  }",
  "  function pspHideOptionalFormulas() {",
  "    document.querySelectorAll('input[placeholder]').forEach(function(inp) {",
  "      var ph = inp.getAttribute('placeholder') || '';",
