  "      if (!m) return;",
  "      if (b.closest('#empModal')) {",
  "        if (tx === 'انصراف' || tx === 'ذخیره') setTimeout(function() { m.removeAttribute('data-psp-per-code'); }, 2600);",
  "      } else if (tx.indexOf('ویرایش') >= 0 || tx.indexOf('افزودن کارمند') >= 0) {",
  "        m.removeAttribute('data-psp-per-code');",
  "      }",
  "    }, true);",
  "  }",
  "  function pspCollectEmpExtraFields(empObj) {",
  "    if (!empObj) return empObj;",
  "    var f = document.getElementById('e_fatherName');",
  "    var m = document.getElementById('e_mobile_psp') || document.getElementById('e_mobile');",
  "    var a = document.getElementById('e_address');",
  "    if (f) empObj.fatherName = String(f.value || '').trim();",
  "    if (m) empObj.mobile = String(m.value || '').trim();",
  "    if (a) empObj.address = String(a.value || '').trim();",
  "    return empObj;",
  "  }",
  "  function pspWireEmpPersonalSave() {",
  "    if (window.__pspPerSaveWired) return;",
  "    window.__pspPerSaveWired = true;",
  "    document.addEventListener('click', function(ev) {",
  "      try {",
  "        var t = ev.target;",
  "        if (!t) return;",
  "        var btn = t.closest ? t.closest('button,a,.btn') : t;",
  "        if (!btn) return;",
  "        var tx = String(btn.textContent || '').replace(/\s+/g, ' ').trim();",
  "        if (tx !== 'ذخیره' && tx.indexOf('ذخیره') !== 0) return;",
  "        var modal = document.getElementById('empModal');",
  "        if (!modal || !btn.closest('#empModal')) return;",
  "        if (btn.id === 'pspStickySave' || btn.id === 'pspManagerSaveBtn' || btn.id === 'pspPortalSaveBtn' || btn.id === 'pspExtraSave') return;",
  "        var codeEl = document.getElementById('e_code') || document.getElementById('editEmpId');",
  "        var code = codeEl ? String(codeEl.value || '').trim() : '';",
  "        if (!code) return;",
  "        var f = document.getElementById('e_fatherName');",
  "        var m = document.getElementById('e_mobile_psp') || document.getElementById('e_mobile');",
  "        var a = document.getElementById('e_address');",
  "        var fatherName = f ? String(f.value || '').trim() : '';",
  "        var mobile = m ? String(m.value || '').trim() : '';",
  "        var address = a ? String(a.value || '').trim() : '';",
  "        function applyTo(emp) {",
  "          if (!emp) return;",
  "          if (fatherName) emp.fatherName = fatherName;",
  "          if (mobile) { emp.mobile = mobile; emp.phone = mobile; }",
  "          if (address) emp.address = address;",
  "        }",
  "        if (window.data && Array.isArray(window.data.employees)) {",
  "          var emp = window.data.employees.find(function(e){ return String(e.code) === code; });",
  "          applyTo(emp);",
  "        }",
  "        if (window.__pspLastEmpData && String(window.__pspLastEmpData.code) === code) applyTo(window.__pspLastEmpData);",
  "        window.__pspPendingPersonal = { code: code, fatherName: fatherName, mobile: mobile, address: address };",
  "        function reApply() {",
  "          try {",
  "            var p = window.__pspPendingPersonal;",
  "            if (!p || !p.code || !window.data || !Array.isArray(window.data.employees)) return;",
  "            var emp = window.data.employees.find(function(e){ return String(e.code) === String(p.code); });",
  "            if (emp) {",
  "              if (p.fatherName) emp.fatherName = p.fatherName;",
  "              if (p.mobile) { emp.mobile = p.mobile; emp.phone = p.mobile; }",
  "              if (p.address) emp.address = p.address;",
  "            }",
  "            if (!window.data.employeeExtras) window.data.employeeExtras = {};",
  "            if (!window.data.employeeExtras[p.code]) window.data.employeeExtras[p.code] = {};",
  "            window.data.employeeExtras[p.code].personal = { fatherName: p.fatherName || '', mobile: p.mobile || '', address: p.address || '' };",
  "          } catch (eR) {}",
  "        }",
  "        [0, 100, 400, 1000, 2000].forEach(function(ms){ setTimeout(reApply, ms); });",
  "        setTimeout(function() {",
  "          try {",
  "            var p = window.__pspPendingPersonal;",
  "            if (!p || !p.code) return;",
  "            fetch('/api/admin/employee-extra', {",
  "              method: 'POST',",
  "              credentials: 'same-origin',",
  "              headers: { 'Content-Type': 'application/json' },",
  "              body: JSON.stringify({ empCode: p.code, personal: { fatherName: p.fatherName, mobile: p.mobile, address: p.address } })",
  "            }).catch(function(){});",
  "          } catch (e2) {}",
  "        }, 600);",
  "      } catch (e1) {}",
  "    }, true);",
  "  }",
  "  try { pspWireEmpPersonalSave(); } catch (eW) {}",
  "  function pspWatchEmpModalForPersonal() {",
  "    if (window.__pspPerWatch) return;",
  "    window.__pspPerWatch = true;",
  "    // بلافاصله بعد از کلیک ویرایش",
  "    document.addEventListener('click', function(ev) {",
  "      try {",
  "        var t = ev.target;",
  "        if (!t) return;",
  "        var btn = t.closest ? t.closest('button,a,.btn') : t;",
  "        if (!btn) return;",
  "        var tx = String(btn.textContent || '').replace(/\\s+/g, ' ').trim();",
  "        if (tx.indexOf('ویرایش') < 0 && tx.indexOf('افزودن کارمند') < 0) return;",
  "        try { var _mm = document.getElementById('empModal'); if (_mm) _mm.removeAttribute('data-psp-per-fetched'); } catch(_e) {}",
  "        // چند بار پشت‌سرهم تا با رندر فرم اصلی هم‌زمان شود",
