  "    if (soft.indexOf('بانک') >= 0) return 'bankName';",
  "    if (soft.indexOf('شبا') >= 0 || soft.indexOf('حساب') >= 0) return 'accountNumber';",
  "    if (soft.indexOf('بیمه') >= 0 && soft.indexOf('تکمیلی') < 0) return 'insuranceNo';",
  "    if (soft.indexOf('تکمیلی') >= 0) return 'supplementaryInsurance';",
  "    if (soft.indexOf('سوابق قبلی') >= 0 && soft.indexOf('سال') >= 0) return 'priorExpY';",
