  "      '<div style=\"font-weight:600;font-size:0.8rem;margin:8px 0 4px;\">گیرندگان <span id=\"pspBcCount\" style=\"color:#0f766e;font-weight:400;\"></span></div>' +",
  "      '<div style=\"display:flex;gap:6px;flex-wrap:wrap;align-items:center;margin-bottom:6px;\">' +",
  "      '<button type=\"button\" class=\"btn btn-outline btn-sm\" id=\"pspBcAll\">همه</button>' +",
