  "      '<div style=\"margin-top:10px;display:flex;gap:8px;align-items:center;\"><button type=\"button\" class=\"btn btn-primary btn-sm\" id=\"pspBcSend\">ارسال پیام</button><span id=\"pspBcStatus\" style=\"font-size:0.8rem;\"></span></div>' +",
  "      '</div></details>' +",
  "      '<details id=\"pspBcArchBox\" style=\"border:1px solid #99f6e4;border-radius:10px;margin-bottom:12px;background:#fff;\">' +",
  "      '<summary style=\"cursor:pointer;padding:10px 12px;font-weight:700;color:#0f766e;\">🗂 بایگانی پیام‌های ارسال‌شده <span id=\"pspBcArchCount\" style=\"font-weight:400;color:#64748b;\"></span></summary>' +",
  "      '<div style=\"padding:10px 12px;overflow:auto;\"><button type=\"button\" class=\"btn btn-outline btn-sm\" id=\"pspBcReload\" style=\"margin-bottom:8px;\">بروزرسانی</button><div id=\"pspBcArchive\"></div></div></details>' +",
  "      '<div style=\"font-weight:700;margin:14px 0 6px;color:#0f766e;\">پیام‌های خودکار سیستم (حق اولاد / بیمه تکمیلی)</div>' +",
  "      '<div class=\"form-grid\" style=\"margin-bottom:8px;\">' +",
