  "                var when = e.at ? String(e.at).slice(0, 10) : '';",
  "                return (idx + 1) + ') ' + (e.text || '') + (e.by ? ' [' + e.by + ']' : '') + (when ? ' (' + when + ')' : '');",
  "              }).join(' | ');",
  "            }",
  "            return c.editNote || '';",
  "          }",
  "          var th = 'border:1px solid #e2e8f0;padding:2px 3px;text-align:center;font-size:0.7rem;white-space:nowrap;';",
  "          var td = 'border:1px solid #e2e8f0;padding:2px 3px;text-align:center;font-size:0.7rem;';",
  "          function ctrYearOf(c) {",
  "            var d = String(c.startDate || c.endDate || c.createdAt || '');",
  "            var m = d.match(/(\\d{4})/);",
  "            return m ? m[1] : 'بدون سال';",
  "          }",
  "          var byYear = {};",
