  "          });",
  "          var years = Object.keys(byYear).sort(function(a, b) { return Number(b) - Number(a); });",
  "          if (!window.__pspCtrOpenYears) window.__pspCtrOpenYears = {};",
  "          var curSysY = String((document.getElementById('pspCurYear') || {}).value || '');",
  "          if (curSysY && window.__pspCtrOpenYears[curSysY] == null) window.__pspCtrOpenYears[curSysY] = true;",
  "          function rowHtml(c) {",
  "            var approved = (c.adminApproved === true || c.adminApproved === 1 || c.adminApproved === 'true' || c.status === 'active' || c.status === 'approved');",
  "            var stt = approved ? (c.status || 'active') : 'منتظر';",
  "            if (approved && !c.signedFileName) stt = (stt || 'active') + ' / بدون امضا';",
  "            var nm = splitName(c);",
