  "            if (unsigned) rowStyle += 'background:#fffbeb;';",
  "            var editNote = allEdits(c);",
  "            var h = '<tr style=\"' + rowStyle + '\">';",
  "            h += '<td style=\"' + td + '\">' + (c.empCode || '') + '</td>';",
