  "            h += '<td style=\"' + td + 'overflow:hidden;text-overflow:ellipsis;\" title=\"' + (nm.ln || '') + '\">' + (nm.ln || '') + '</td>';",
  "            h += '<td style=\"' + td + '\">' + typeLabel(c.type) + '</td>';",
  "            h += '<td style=\"' + td + '\">' + durLabel(c.durationMonths) + '</td>';",
  "            h += '<td style=\"' + td + 'direction:ltr;font-size:0.65rem;\">' + (c.startDate || '') + '</td>';",
  "            h += '<td style=\"' + td + 'direction:ltr;font-size:0.65rem;\">' + (c.endDate || '') + '</td>';",
  "            h += '<td style=\"' + td + '\">' + stt + '</td>';",
  "            h += '<td style=\"' + td + 'text-align:right;font-size:0.65rem;color:#475569;\" title=\"' + (editNote || '').replace(/\"/g, '&quot;') + '\">' + (editNote || '—') + '</td>';",
  "            h += '<td style=\"' + td + 'white-space:nowrap;\">';",
  "            if (!c.adminApproved) h += '<button type=\"button\" class=\"btn btn-outline btn-sm psp-ctr-approve\" data-id=\"' + c.id + '\" style=\"padding:1px 5px;font-size:0.68rem;margin-left:2px;\">تأیید</button>';",
  "            h += '<button type=\"button\" class=\"btn btn-outline btn-sm psp-ctr-edit\" data-id=\"' + c.id + '\" style=\"padding:1px 5px;font-size:0.68rem;margin-left:2px;color:#1d4ed8;border-color:#93c5fd;\">ویرایش</button>';",
  "            h += '<button type=\"button\" class=\"btn btn-outline btn-sm psp-ctr-upload\" data-id=\"' + c.id + '\" style=\"padding:1px 5px;font-size:0.68rem;margin-left:2px;color:#0f766e;border-color:#99f6e4;\" title=\"' + (c.signedFileName ? ('فایل: ' + c.signedFileName) : 'آپلود امضا') + '\">' + (c.signedFileName ? 'فایل✓' : 'آپلود') + '</button>';",
  "            h += '<button type=\"button\" class=\"btn btn-outline btn-sm psp-ctr-del\" data-id=\"' + c.id + '\" style=\"padding:1px 5px;font-size:0.68rem;color:#b91c1c;\">حذف</button>';",
  "            h += '</td></tr>';",
  "            return h;",
  "          }",
  "          var thead = '<thead><tr style=\"background:#f8fafc;\">' +",
  "            '<th style=\"' + th + 'width:6%;\">کد</th>' +",
