  "                body: JSON.stringify({",
  "                  code: (window.__pspTsDaily||{}).code,",
  "                  year: window.__pspTsYear,",
  "                  month: window.__pspTsMonth,",
  "                  updateWorkDays: true,",
  "                  days: days",
  "                })",
  "              }).then(function(r){return r.json()}).then(function(res){",
  "                if (st) {",
