  "                  if (!date || !map[date]) return;",
  "                  var r = map[date];",
  "                  var el;",
  "                  el = tr.querySelector('.ts-in1'); if (el) el.value = r.in1;",
  "                  el = tr.querySelector('.ts-out1'); if (el) el.value = r.out1;",
  "                  el = tr.querySelector('.ts-in2'); if (el) el.value = r.in2;",
  "                  el = tr.querySelector('.ts-out2'); if (el) el.value = r.out2;",
  "                  el = tr.querySelector('.ts-note'); if (el && r.note) el.value = r.note;",
  "                  n++;",
  "                });",
  "                var st = document.getElementById('pspTsDayStatus');",
  "                if (st) { st.style.color='#0f766e'; st.textContent = n + ' روز از فایل. «ذخیره» را بزنید.'; }",
  "              };",
  "              reader.readAsText(f);",
  "            };",
  "          }, 50);",
  "        } else if (!document.getElementById('pspTsCode').value.trim()) {",
  "          html += '<p style=\"font-size:0.8rem;color:#0f766e;margin-bottom:8px;\">برای جدول روزبه‌روز و ثبت ورود/خروج، یک کد پرسنلی وارد کنید.</p>';",
  "        }",
  "        var rows = (j.rows || []).map(function(x){",
  "          return '<tr><td style=\"text-align:center;vertical-align:middle;padding:10px 12px;border-bottom:1px solid #e2e8f0;white-space:nowrap;\"><input type=\"checkbox\" class=\"psp-bulk-code\" value=\"'+x.code+'\"></td><td style=\"text-align:center;vertical-align:middle;padding:10px 12px;border-bottom:1px solid #e2e8f0;white-space:nowrap;\">'+x.code+'</td><td style=\"text-align:right;vertical-align:middle;padding:10px 12px;border-bottom:1px solid #e2e8f0;\">'+(x.fullName||'')+'</td><td style=\"text-align:center;vertical-align:middle;padding:10px 12px;border-bottom:1px solid #e2e8f0;white-space:nowrap;\">'+(x.unit||'')+'</td><td style=\"text-align:center;vertical-align:middle;padding:10px 12px;border-bottom:1px solid #e2e8f0;white-space:nowrap;\">'+(x.managerCode||'-')+'</td><td style=\"text-align:center;vertical-align:middle;padding:10px 12px;border-bottom:1px solid #e2e8f0;white-space:nowrap;\"><b>'+(x.workDays!=null?x.workDays:0)+'</b></td><td style=\"text-align:center;vertical-align:middle;padding:10px 12px;border-bottom:1px solid #e2e8f0;white-space:nowrap;\">'+(x.childrenEligibleCount!=null?x.childrenEligibleCount:(x.childCount!=null?x.childCount:'-'))+'</td><td style=\"text-align:center;vertical-align:middle;padding:10px 12px;border-bottom:1px solid #e2e8f0;white-space:nowrap;\">'+(x.leaveDays!=null?x.leaveDays:0)+'</td><td style=\"text-align:center;vertical-align:middle;padding:10px 12px;border-bottom:1px solid #e2e8f0;white-space:nowrap;\">'+(x.hourlyLeave!=null?x.hourlyLeave:0)+'</td><td style=\"text-align:center;vertical-align:middle;padding:10px 12px;border-bottom:1px solid #e2e8f0;white-space:nowrap;\">'+(x.missions!=null?x.missions:0)+'</td></tr>';",
  "        }).join('');",
  "        html += '<h4 style=\"margin-top:14px;\">خلاصه ماه</h4>';",
