  "          '<button type=\"button\" class=\"btn btn-outline btn-sm\" id=\"pspShortAllowSave\" style=\"font-size:0.62rem;padding:2px 6px;height:22px;\">ذخیره سقف</button>' +",
  "          '<label style=\"white-space:nowrap;font-size:0.65rem;\">تاریخ: <input id=\"pspBulkDate\" placeholder=\"1405/01/15\" style=\"width:90px;padding:2px 3px;direction:ltr;font-size:0.65rem;height:22px;\"></label>' +",
  "          '<button type=\"button\" class=\"btn btn-primary btn-sm\" id=\"pspBulkLeave\" style=\"font-size:0.62rem;padding:2px 6px;height:22px;white-space:nowrap;\">مرخصی ساعتی گروهی</button>' +",
  "          '<button type=\"button\" class=\"btn btn-outline btn-sm\" id=\"pspBulkMission\" style=\"font-size:0.62rem;padding:2px 6px;height:22px;white-space:nowrap;\">مأموریت ساعتی گروهی</button>' +",
  "          '</div>' +",
  "          '<p style=\"color:#64748b;margin:0;font-size:0.75rem;\">تیک بزنید → سیستم روزهای دارای کسر کار را پیدا می‌کند و مرخصی/مأموریت ساعتی ثبت می‌کند. تا سقف مجاز ماهانه، کسر باقی می‌ماند. تاریخ خالی = همه روزهای ماه؛ پر = فقط همان روز.</p>' +",
  "          '<div id=\"pspBulkStatus\" style=\"margin-top:6px;color:#0f766e;\"></div></div>';",
  "        html += '<table id=\"pspBulkTable\" style=\"width:100%;border-collapse:collapse;font-size:0.82rem;margin-top:10px;\"><thead><tr><th style=\"text-align:center;vertical-align:middle;padding:10px 12px;background:#f0fdfa;border-bottom:2px solid #99f6e4;white-space:nowrap;font-weight:600;\"><input type=\"checkbox\" id=\"pspBulkAll\"></th><th style=\"text-align:center;vertical-align:middle;padding:10px 12px;background:#f0fdfa;border-bottom:2px solid #99f6e4;white-space:nowrap;font-weight:600;\">کد</th><th style=\"text-align:center;vertical-align:middle;padding:10px 12px;background:#f0fdfa;border-bottom:2px solid #99f6e4;white-space:nowrap;font-weight:600;\">نام</th><th style=\"text-align:center;vertical-align:middle;padding:10px 12px;background:#f0fdfa;border-bottom:2px solid #99f6e4;white-space:nowrap;font-weight:600;\">واحد</th><th style=\"text-align:center;vertical-align:middle;padding:10px 12px;background:#f0fdfa;border-bottom:2px solid #99f6e4;white-space:nowrap;font-weight:600;\">مدیر</th><th style=\"text-align:center;vertical-align:middle;padding:10px 12px;background:#f0fdfa;border-bottom:2px solid #99f6e4;white-space:nowrap;font-weight:600;\">کارکرد (روز)</th><th style=\"text-align:center;vertical-align:middle;padding:10px 12px;background:#f0fdfa;border-bottom:2px solid #99f6e4;white-space:nowrap;font-weight:600;\">حق اولاد</th><th style=\"text-align:center;vertical-align:middle;padding:10px 12px;background:#f0fdfa;border-bottom:2px solid #99f6e4;white-space:nowrap;font-weight:600;\">مرخصی روزانه</th><th style=\"text-align:center;vertical-align:middle;padding:10px 12px;background:#f0fdfa;border-bottom:2px solid #99f6e4;white-space:nowrap;font-weight:600;\">مرخصی ساعتی</th><th style=\"text-align:center;vertical-align:middle;padding:10px 12px;background:#f0fdfa;border-bottom:2px solid #99f6e4;white-space:nowrap;font-weight:600;\">مأموریت روزانه</th></tr></thead><tbody>' + rows + '</tbody></table>';",
  "        out.innerHTML = html;",
  "        // سقف کسر + گروهی",
  "        fetch('/api/admin/shortfall-settings',{credentials:'same-origin'}).then(function(r){return r.json()}).then(function(s){",
  "          var el=document.getElementById('pspShortAllow');",
  "          if(el && s && s.ok && s.monthlyShortfallAllowanceHours!=null && s.monthlyShortfallAllowanceHours!=='') el.value=s.monthlyShortfallAllowanceHours;",
  "        }).catch(function(){});",
  "        var all=document.getElementById('pspBulkAll');",
  "        if(all) all.onchange=function(){ document.querySelectorAll('.psp-bulk-code').forEach(function(c){ c.checked=all.checked; }); };",
  "        function selectedCodes(){ var a=[]; document.querySelectorAll('.psp-bulk-code:checked').forEach(function(c){ a.push(c.value); }); return a; }",
  "        function runBulk(kind){",
  "          var codes=selectedCodes();",
  "          if(!codes.length){ alert('حداقل یک نفر را تیک بزنید'); return; }",
  "          var st=document.getElementById('pspBulkStatus');",
