  "        + '<div><label style=\"font-size:0.7rem;display:block;\">پایان</label><input id=\"pspDsEnd\" placeholder=\"15:30\" dir=\"ltr\" style=\"width:72px;font-family:inherit;\"></div>'",
  "        + '<label style=\"display:flex;align-items:center;gap:3px;font-family:inherit;\"><input type=\"checkbox\" id=\"pspDsSkipOfficial\" checked> رد تعطیل رسمی</label>'",
