  "        + '<div style=\"margin-top:6px;color:#64748b;font-size:0.72rem;\">پیش‌فرض از ساعت کاری نوع قرارداد. حاشیه آبی = روز سفارشی. «ذخیره تعطیلات» را بزنید.</div>';",
