  "        if (window.__pspTsColVis.portalTabs.ot === false) window.__pspTsColVis.timesheetCols.ot = false;",
  "        if (window.__pspTsColVis.portalTabs.absenceHourly === false) window.__pspTsColVis.timesheetCols.abs = false;",
  "        try { localStorage.setItem('pspUserAccess', JSON.stringify(window.__pspTsColVis)); } catch(e){}",
