  "        .then(function(r){ return r.json(); }).then(function(j){",
  "          if (!j.ok) { box.innerHTML = '<div style=\"padding:6px;color:#b91c1c;font-size:0.78rem;\">' + (j.message || j.error || 'خطا') + '</div>'; if (info) info.textContent = ''; return; }",
  "          var list = j.grants || [];",
