  "            h += '<td style=\"padding:3px 5px;border-bottom:1px solid #f1f5f9;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;\">' + (g.typeName || g.typeId || '') + '</td>';",
  "            h += '<td style=\"padding:3px 5px;border-bottom:1px solid #f1f5f9;direction:ltr;font-size:0.7rem;\">' + (g.dateFrom || '—') + '</td>';",
