  "        return arr.map(function(t){ return '<option value=\"' + t.id + '\"' + (String(t.id) === cur ? ' selected' : '') + '>' + t.name + '</option>'; }).join('');",
  "      }",
  "      if (!window.__pspReqOpenYears) window.__pspReqOpenYears = {};",
