  "      if (cy && window.__pspReqOpenYears[cy] == null) window.__pspReqOpenYears[cy] = true;",
  "      var thead = '<thead><tr><th>کد</th><th>نام</th><th>نوع</th><th>از تاریخ</th><th>تا تاریخ</th><th>از ساعت</th><th>تا ساعت</th><th>محل</th><th>دلیل</th><th>وضعیت</th><th>عملیات</th></tr></thead>';",
  "      function rowHtml(x, i) {",
  "        return '<tr data-i=\"' + i + '\">' +",
  "          '<td><input data-f=\"empCode\" value=\"' + (x.empCode || '') + '\" style=\"width:80px\"></td>' +",
  "          '<td style=\"white-space:nowrap\">' + (x.empName || '') + '</td>' +",
  "          '<td><select data-f=\"typeId\">' + typeOptsFor(x) + '</select></td>' +",
  "          '<td><input data-f=\"startDate\" value=\"' + (x.startDate || '') + '\" style=\"width:90px\" dir=\"ltr\"></td>' +",
  "          '<td><input data-f=\"endDate\" value=\"' + (x.endDate || '') + '\" style=\"width:90px\" dir=\"ltr\"></td>' +",
  "          '<td><input data-f=\"fromTime\" value=\"' + (x.fromTime || '') + '\" style=\"width:60px\" dir=\"ltr\"></td>' +",
  "          '<td><input data-f=\"toTime\" value=\"' + (x.toTime || '') + '\" style=\"width:60px\" dir=\"ltr\"></td>' +",
  "          '<td><input data-f=\"place\" value=\"' + (x.place || '') + '\" style=\"width:80px\"></td>' +",
  "          '<td><input data-f=\"reason\" value=\"' + (x.reason || '') + '\" style=\"width:140px\"></td>' +",
  "          '<td><select data-f=\"status\">' +",
  "            '<option value=\"pending\"' + (x.status === 'pending' ? ' selected' : '') + '>در انتظار</option>' +",
  "            '<option value=\"approved_l1\"' + (x.status === 'approved_l1' ? ' selected' : '') + '>تأیید سطح ۱</option>' +",
  "            '<option value=\"approved\"' + (x.status === 'approved' ? ' selected' : '') + '>تأیید نهایی</option>' +",
  "            '<option value=\"rejected\"' + (x.status === 'rejected' ? ' selected' : '') + '>رد شده</option>' +",
