  "          html += '<button type=\"button\" class=\"psp-req-year-tog\" data-year=\"' + y + '\" style=\"width:100%;text-align:right;padding:8px 12px;background:#ecfdf5;border:0;cursor:pointer;font-family:inherit;font-size:0.82rem;font-weight:700;color:#0f766e;display:flex;align-items:center;gap:8px;\">';",
  "          html += '<span style=\"font-size:1rem;width:1.2em;text-align:center;\">' + (open ? '−' : '+') + '</span>';",
