  "      }",
  "    } catch (e1) {}",
  "    // Intl با تقویم فارسی — روی موبایل پایدارتر از toLocaleDateString",
  "    try {",
  "      var fmt = new Intl.DateTimeFormat('en-u-ca-persian', { year: 'numeric' });",
  "      var y2 = ok(fmt.format(new Date()));",
  "      if (y2) return y2;",
  "    } catch (e2) {}",
  "    try {",
  "      var fmt2 = new Intl.DateTimeFormat('fa-IR-u-ca-persian', { year: 'numeric' });",
  "      var parts = fmt2.formatToParts(new Date());",
  "      for (var i = 0; i < parts.length; i++) {",
  "        if (parts[i].type === 'year') {",
  "          var y3 = ok(fromFaNum(parts[i].value));",
  "          if (y3) return y3;",
  "        }",
  "      }",
  "    } catch (e3) {}",
  "    // تبدیل تقریبی میلادی → شمسی",
  "    try {",
  "      var g = new Date();",
