  "  function compressLogoFile(file, cb) {",
  "    var rdr = new FileReader();",
  "    rdr.onerror = function () { cb(new Error('خواندن فایل ناموفق')); };",
  "    rdr.onload = function () {",
  "      var img = new Image();",
  "      img.onerror = function () { cb(new Error('تصویر نامعتبر')); };",
  "      img.onload = function () {",
  "        try {",
  "          var maxW = 360, maxH = 160;",
  "          var w = img.width, h = img.height;",
  "          var scale = Math.min(1, maxW / w, maxH / h);",
  "          var cw = Math.max(1, Math.round(w * scale));",
  "          var ch = Math.max(1, Math.round(h * scale));",
  "          var c = document.createElement('canvas');",
  "          c.width = cw; c.height = ch;",
  "          var ctx = c.getContext('2d');",
  "          ctx.fillStyle = '#ffffff';",
  "          ctx.fillRect(0, 0, cw, ch);",
  "          ctx.drawImage(img, 0, 0, cw, ch);",
  "          var out = c.toDataURL('image/png');",
  "          // اگر خیلی بزرگ بود jpeg امتحان کن",
  "          if (out.length > 180000) {",
  "            out = c.toDataURL('image/jpeg', 0.82);",
  "          }",
