  "            st +",
  "            '</span>'",
  "        })",
  "      );",
  "      row.appendChild(",
  "        el('div', {",
  "          style: 'color:#475569;',",
  "          text:",
  "            (x.name || '') +",
  "            ' (' +",
  "            (x.code || '') +",
  "            ') — ' +",
  "            ((x.mains && x.mains[0] && (x.mains[0].name || x.mains[0].line || x.mains[0])) || '')",
  "        })",
  "      );",
  "      var acts = el('div', {",
  "        style: 'margin-top:4px;display:flex;gap:4px;flex-wrap:wrap;'",
  "      });",
  "      function mkBtn(lab, act, color) {",
  "        var b = el(",
  "          'button',",
  "          {",
  "            type: 'button',",
  "            className: 'btn btn-outline btn-sm',",
  "            style: 'padding:1px 6px;font-size:0.7rem;' + (color || '')",
  "          },",
  "          [lab]",
  "        );",
  "        b.onclick = function () {",
  "          onArchAct(act, x.id);",
  "        };",
  "        return b;",
  "      }",
  "      acts.appendChild(mkBtn('بارگذاری', 'load'));",
  "      acts.appendChild(mkBtn('کپی (شماره جدید)', 'copy'));",
  "      acts.appendChild(mkBtn('ابطال', 'void', 'color:#b91c1c;'));",
  "      row.appendChild(acts);",
  "      box.appendChild(row);",
  "    });",
  "  }",
  "  function onArchAct(act, id) {",
  "    var list = loadArch();",
  "    var item = null;",
  "    for (var i = 0; i < list.length; i++) if (list[i].id === id) item = list[i];",
  "    if (!item) return;",
  "    if (act === 'void') {",
  "      if (!confirm('ابطال گواهی ' + item.letterNo + '؟')) return;",
  "      item.status = 'void';",
  "      saveArch(list);",
  "      renderArch((document.getElementById('pspCertSearch') || {}).value, 'archive'); renderArch('', 'draft');",
  "      setSt(true, 'باطل شد');",
  "      return;",
  "    }",
  "    if (act === 'copy') {",
  "      var no = nextLetterNo();",
  "      var copy = {",
  "        id: 'c' + Date.now().toString(36),",
  "        letterNo: no,",
  "        date: todayFa(),",
  "        code: item.code,",
  "        name: item.name,",
  "        mains: (item.mains || []).slice(),",
  "        ccs: (item.ccs || []).slice(),",
  "        body: item.body,",
  "        tplName: item.tplName,",
  "        status: 'draft',",
  "        paper: item.paper || 'A4',",
  "        savedAt: new Date().toISOString()",
  "      };",
  "      list.unshift(copy);",
  "      saveArch(list);",
  "      commitLetterNo(no);",
  "      loadItemToForm(copy);",
  "      renderArch('', 'archive'); renderArch('', 'draft');",
  "      setSt(true, 'کپی با شماره ' + no);",
  "      return;",
  "    }",
  "    if (act === 'load') {",
  "      loadItemToForm(item);",
  "      setSt(true, 'بارگذاری شد: ' + item.letterNo);",
  "    }",
  "  }",
  "  function loadItemToForm(item) {",
  "    if (!item) return;",
  "    var ta = document.getElementById('pspCertBody');",
  "    if (ta) ta.value = item.body || '';",
  "    var c = document.getElementById('pspCertCode');",
  "    if (c) c.value = item.code || '';",
  "    var n = document.getElementById('pspCertLetterNo');",
  "    if (n) n.value = item.letterNo || '';",
  "    var d = document.getElementById('pspCertDate');",
  "    if (d) d.value = item.date || '';",
  "    setRcpts('pspCertMainList', item.mains || []);",
  "    setRcpts('pspCertCcList', item.ccs || []);",
  "    var info = document.getElementById('pspCertEmpInfo');",
  "    if (info)",
  "      info.textContent = (item.name || '') + ' | ' + (item.code || '') + ' | ' + (item.status || '');",
  "  }",
  "  function snapshotCurrent(status) {",
  "    var code = String((document.getElementById('pspCertCode') || {}).value || '').trim();",
  "    var emp = getEmp(code);",
  "    var name = emp",
  "      ? emp.fullName ||",
  "        emp.name ||",
  "        [emp.firstName, emp.lastName].filter(Boolean).join(' ') ||",
  "        code",
  "      : code;",
  "    var letterNo =",
  "      String((document.getElementById('pspCertLetterNo') || {}).value || '').trim() ||",
  "      nextLetterNo();",
  "    var dateFa =",
  "      String((document.getElementById('pspCertDate') || {}).value || '').trim() || todayFa();",
  "    var body = String((document.getElementById('pspCertBody') || {}).value || '');",
  "    var tpl = selectedTpl();",
  "    return {",
  "      id: 'c' + Date.now().toString(36),",
  "      letterNo: letterNo,",
  "      date: dateFa,",
  "      code: code,",
  "      name: name,",
  "      mains: collectRcpts('pspCertMainList'),",
  "      ccs: collectRcpts('pspCertCcList'),",
  "      body: body,",
  "      tplName: tpl ? tpl.name : '',",
  "      status: status || 'draft',",
  "      paper: getPaper(),",
  "      savedAt: new Date().toISOString()",
  "    };",
  "  }",
  "  function buildUi(host) {",
  "    host.innerHTML = '';",
  "    var card = el('div', {",
  "      style: 'padding:12px;max-width:920px;'",
  "    });",
  "    card.appendChild(",
  "      el('div', {",
  "        className: 'section-title',",
  "        text: 'گواهی / نامه رسمی',",
  "        style: 'margin-bottom:8px;'",
  "      })",
  "    );",
  "    card.appendChild(",
  "      el('div', {",
  "        id: 'pspCertStatus',",
  "        style: 'font-size:0.8rem;color:#0f766e;min-height:1.2em;margin-bottom:8px;'",
  "      })",
  "    );",
  "",
  "    // templates",
  "    var s1 = el('div', {",
  "      style: 'padding:12px;border:1px solid #e2e8f0;border-radius:10px;background:#fff;margin-bottom:12px;'",
  "    });",
  "    s1.appendChild(",
  "      el('div', {",
  "        style: 'font-size:0.82rem;font-weight:700;color:#0f766e;margin-bottom:8px;',",
  "        text: '۱) قالب نامه'",
  "      })",
  "    );",
  "    s1.appendChild(",
  "      el('select', {",
  "        id: 'pspCertTplSelect',",
  "        style: 'width:100%;max-width:420px;padding:7px 9px;border:1px solid #99f6e4;border-radius:8px;margin-bottom:8px;display:block;'",
  "      })",
  "    );",
  "    s1.appendChild(",
  "      el('input', {",
  "        id: 'pspCertTplName',",
  "        placeholder: 'نام قالب',",
  "        style: 'width:100%;max-width:420px;padding:7px 9px;border:1px solid #99f6e4;border-radius:8px;margin-bottom:8px;display:block;'",
  "      })",
  "    );",
  "    var tb = el('div', { style: 'display:flex;gap:8px;flex-wrap:wrap;margin-bottom:8px;' });",
  "    tb.appendChild(el('button', { type: 'button', className: 'btn btn-primary btn-sm', id: 'pspCertTplSave' }, ['ذخیره قالب']));",
  "    tb.appendChild(el('button', { type: 'button', className: 'btn btn-outline btn-sm', id: 'pspCertTplNew' }, ['متن پیش‌فرض']));",
